steps.script:
function transform(ctx) {
  var MAP = { "校园网": "学校互联网服务", "移动": "移动互联网服务", "联通": "联通互联网服务", "电信": "电信互联网服务" };
  var isp = (ctx.isp || "").trim();
  var service = isp ? (MAP[isp] !== undefined ? MAP[isp] : isp) : "学校互联网服务";
  if (!ctx.vars.portal_host) throw new Error("未能从跳转页提取门户主机，请核对本校门户地址");
  return { eu: url_encode(ctx.username || ""), ep: url_encode(ctx.password || ""), eservice: url_encode(url_encode(service)), qse: url_encode(ctx.vars.queryString || "") };
}
